CREATE TABLE win14_transactions (sequence_no INTEGER PRIMARY KEY, amount INTEGER NOT NULL);
INSERT INTO win14_transactions VALUES (1, 10), (2, 20), (3, 15), (4, 5);
SELECT sequence_no, amount, SUM(amount) OVER (ORDER BY sequence_no ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM win14_transactions ORDER BY sequence_no;

